mapper.select:
SELECT c.id, p.name AS parent_name, -- 父分类名称 c.name, CASE c.category_type WHEN 1 THEN '空间分类' WHEN 2 THEN '风格分类' WHEN 3 THEN '材质分类' WHEN 4 THEN '功能分类' ELSE '其他' END AS category_type, -- 转换为中文类型名称 CASE c.is_active WHEN 1 THEN true ELSE false END AS is_active, -- 转换为Boolean类型 c.level, c.path, c.created_at, c.updated_at FROM category c LEFT JOIN category p ON c.parent_id = p.id AND p.is_deleted = 0 WHERE c.is_deleted = 0
AND c.name LIKE CONCAT('%', #{name}, '%')
AND c.category_type = #{categoryType}
AND c.is_active = #{isActive}
AND c.level = #{level}
ORDER BY c.sort_order ASC, c.created_at DESC
